# A 16 by 16 pixel image, stored as RGB hexadecimal color strings.
from pathlib import Path
import re


def pixel_render(app):
    app.PixelCanvas.delete("all")
    for row in range(16):
        for column in range(16):
            x, y = column * 32, row * 32
            app.PixelCanvas.create_rectangle(x, y, x + 32, y + 32, fill=app.pixel_grid[row][column], outline="#b0b0b0", tags=(f"pixel_{row}_{column}",))


def pixel_choose(app, color):
    # Restrict colors to safe RGB hex strings for both exporters.
    if re.fullmatch(r"#[0-9a-fA-F]{6}", color):
        app.pixel_color = color.upper()
        app.StatusLabel.configure(text="Color: " + app.pixel_color)


def pixel_custom_color(app):
    color = colorchooser.askcolor(parent=app.Form1, color=app.pixel_color)[1]
    if color is not None:
        pixel_choose(app, color)


def pixel_draw(app, event):
    # Ignore clicks outside the grid rather than indexing the next row.
    column, row = int(event.x) // 32, int(event.y) // 32
    if not 0 <= row < 16 or not 0 <= column < 16:
        return
    app.pixel_grid[row][column] = app.pixel_color
    app.PixelCanvas.itemconfigure(f"pixel_{row}_{column}", fill=app.pixel_color)


def pixel_clear(app):
    if messagebox.askyesno("Clear pixels", "Clear the entire image?", parent=app.Form1):
        app.pixel_grid = [["#FFFFFF" for column in range(16)] for row in range(16)]
        pixel_render(app)


def pixel_ppm(grid):
    # PPM is a real raster image format and needs no Pillow dependency.
    pixels = bytearray()
    for row in grid:
        for color in row:
            pixels.extend(bytes.fromhex(color[1:]))
    return b"P6\n16 16\n255\n" + bytes(pixels)


def pixel_svg(grid):
    # Export one vector rectangle per pixel; grid lines are editor-only.
    rows = ['<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 16 16" shape-rendering="crispEdges">']
    for y, row in enumerate(grid):
        for x, color in enumerate(row):
            rows.append(f'<rect x="{x}" y="{y}" width="1" height="1" fill="{color}"/>')
    return "\n".join(rows + ["</svg>"])


def pixel_export(app, kind):
    extension = ".ppm" if kind == "ppm" else ".svg"
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=extension, filetypes=[("Pixel image", "*" + extension)])
    if not filename:
        return
    try:
        path = Path(filename)
        if kind == "ppm":
            path.write_bytes(pixel_ppm(app.pixel_grid))
        else:
            path.write_text(pixel_svg(app.pixel_grid), encoding="utf-8")
        app.StatusLabel.configure(text="Exported: " + str(path))
    except (OSError, ValueError) as error:
        messagebox.showerror("Export pixels", str(error), parent=app.Form1)


def pixel_close(app):
    # Images are not autosaved; confirm before destroying the grid.
    if messagebox.askyesno("Close pixels", "Close without exporting?", parent=app.Form1):
        app.root.destroy()
